base_hero_scrim_css:
.hero-scrim {
      position: absolute;
      inset: 0;
      z-index: 1;
      pointer-events: none;
      background:
        linear-gradient(to bottom,
          rgba(13,13,11,0.38) 0%,
          rgba(13,13,11,0.32) 38%,
          rgba(13,13,11,0.68) 68%,
          rgba(13,13,11,0.97) 100%);
    }

injected_styles.hero-mobile-css:
.nw { white-space: nowrap; }
/* phone hero 2026-11-03 item 39: same #4 as desktop (was #36); srcset sized for phones */
@media (max-width: 767px) {
  .hero { background-image: none; }
  .hero-media picture { display: block; width: 100%; height: 100%; }
  .hero-media { bottom: auto; height: var(--mh-h, 64%); }
  .hero-photo { object-position: var(--mh-pos, 52% 60%); }
  .hero-media::after {
    content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 38%;
    background: linear-gradient(to bottom, rgba(13,13,11,0) 0%, var(--charcoal) 100%);
    pointer-events: none;
  }
}

injected_styles.hero-shift-css:
/* hero line-1 fit 2026-11-03: widen subtitle so line 1 fits; shift block left only as far as needed to clear the barrel sauna in #4 */
@media (min-width: 640px) and (max-width: 767px) { .hero-lede { max-width: none; } }
@media (min-width: 768px) {
  .hero-lede { max-width: 44rem; }
  .hero-inner { max-width: none; margin: 0; padding-left: max(var(--pad), min(calc((100vw - 1180px) / 2 + var(--pad)), calc(57.1vw - 706px))); }
}

injected_styles.hero-balance-css:
/* hero text rhythm 2026-11-03 (item 25): even gaps eyebrow/H1/line 1/line 2; airy lede; line 1 wraps 768-1279 to clear the sauna, one line at 1280+ */
.hero .eyebrow { margin-bottom: 1rem; }
.hero h1 { margin-bottom: 1.15rem; }
.hero-lede { line-height: 1.5; margin-bottom: 1.5rem; }
.hero-lede .hl { display: block; }
.hero-lede .hl2 { margin-top: .4em; }
@media (min-width: 768px) and (max-width: 1279px) {
  .hero-lede { max-width: 38ch; }
  .hero h1 { margin-bottom: 1.25rem; }
}
@media (min-width: 1280px) {
  .hero .eyebrow { margin-bottom: 1.15rem; }
  .hero h1 { margin-bottom: 1.4rem; }
  .hero-lede { max-width: none; margin-bottom: 1.7rem; }
  .hero-lede .hl1 { white-space: nowrap; }
}

